package com.jinloes.practice;
public class Solution { public static class TreeNode { public int value; public TreeNode left; public TreeNode right; public TreeNode(int value){this.value=value;} public TreeNode(int value, TreeNode left, TreeNode right){this.value=value;this.left=left;this.right=right;} } private static final class S{TreeNode prev,ans;} public static TreeNode inorderSuccessor(TreeNode root,TreeNode target){if(target==null)return null; S s=new S(); v(root,target,s); return s.ans;} private static void v(TreeNode n,TreeNode t,S s){if(n==null||s.ans!=null)return; v(n.left,t,s); if(s.ans!=null)return; if(s.prev==t){s.ans=n;return;} s.prev=n; v(n.right,t,s);} }
